import {precision} from './precision.js';
// Siluetra geometry adapter. Curve pieces retain their original cubic controls.
import {clone,uid,cubic} from './core.js';
const mix=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});
export function splitCubic(a,b,t){const c=a.out||a,d=b.in||b,A=mix(a,c,t),B=mix(c,d,t),C=mix(d,b,t),D=mix(A,B,t),E=mix(B,C,t),F=mix(D,E,t);return [{...clone(a),out:A},{...F,in:D,out:E,nid:uid(),edgeId:uid(),edgeParents:[...new Set([a.edgeId,...a.edgeParents||[]].filter(Boolean))]},{...clone(b),in:C}];}
export function cubicSlice(a,b,lo=0,hi=1){let left=clone(a),right=clone(b);if(hi<1){const s=splitCubic(left,right,hi);left=s[0];right={...s[1]};delete right.out;}if(lo>0){const s=splitCubic(left,right,lo/hi);left={...s[1]};delete left.in;right=s[2];}if(!a.out&&!b.in){delete left.out;delete right.in;}return [left,right];}
export function pointSegmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t);}
export function flattenCubic(a,b,tolerance=.1){if(!Number.isFinite(tolerance)||tolerance<=0)throw Error('Tolerancia de curva inválida.');const out=[{...a,t:0}];function walk(a,b,lo,hi,depth){if(depth>=18||Math.max(pointSegmentDistance(a.out||a,a,b),pointSegmentDistance(b.in||b,a,b))<=tolerance){if(out.length>=precision.maxCurveSamples)throw Error('La curva es demasiado compleja para esta operación.');out.push({...b,t:hi});return;}const [l,m,r]=splitCubic(a,b,.5),mid=(lo+hi)/2;walk(l,m,lo,mid,depth+1);walk(m,r,mid,hi,depth+1);}walk(a,b,0,1,0);return out;}
export function nearestOnCubic(a,b,p){const poly=flattenCubic(a,b,.15);let best={distance:Infinity,t:0,point:a};for(let i=1;i<poly.length;i++){const u=poly[i-1],v=poly[i],dx=v.x-u.x,dy=v.y-u.y,k=Math.max(0,Math.min(1,((p.x-u.x)*dx+(p.y-u.y)*dy)/(dx*dx+dy*dy||1))),t=u.t+(v.t-u.t)*k,q=cubic(a,b,t),distance=Math.hypot(q.x-p.x,q.y-p.y);if(distance<best.distance)best={distance,t,point:q};}let lo=Math.max(0,best.t-.05),hi=Math.min(1,best.t+.05);for(let i=0;i<35;i++){const l=lo+(hi-lo)/3,r=hi-(hi-lo)/3,lp=cubic(a,b,l),rp=cubic(a,b,r);if(Math.hypot(lp.x-p.x,lp.y-p.y)<Math.hypot(rp.x-p.x,rp.y-p.y))hi=r;else lo=l;}const t=(lo+hi)/2,q=cubic(a,b,t),distance=Math.hypot(q.x-p.x,q.y-p.y);return distance<best.distance?{distance,t,point:q}:best;}
export function adaptivePoints(path,tolerance=.1){if(!path.nodes?.length)return [];const out=[path.nodes[0]];for(let i=0;i<path.nodes.length-(path.closed?0:1);i++){const ps=flattenCubic(path.nodes[i],path.nodes[(i+1)%path.nodes.length],tolerance).slice(1);if(out.length+ps.length>precision.maxPathSamples)throw Error('El trazado es demasiado complejo para esta operación.');out.push(...ps);}return out;}
// The line/curve intersection solves the signed-distance cubic, then clips to the finite line.
export function cubicLineRoots(a,b,p,q){const dx=q.x-p.x,dy=q.y-p.y,len=dx*dx+dy*dy;if(len<1e-20)return [];const f=t=>{const x=cubic(a,b,t);return (x.x-p.x)*dy-(x.y-p.y)*dx;},c=a.out||a,d=b.in||b,values=[a,c,d,b].map(x=>(x.x-p.x)*dy-(x.y-p.y)*dx),A=-values[0]+3*values[1]-3*values[2]+values[3],B=3*values[0]-6*values[1]+3*values[2],C=-3*values[0]+3*values[1],critical=[0,1];if(Math.abs(A)<1e-14){if(Math.abs(B)>1e-14)critical.push(-C/(2*B));}else{const disc=4*B*B-12*A*C;if(disc>=0)critical.push((-2*B+Math.sqrt(disc))/(6*A),(-2*B-Math.sqrt(disc))/(6*A));}const ts=critical.filter(t=>t>=0&&t<=1).sort((a,b)=>a-b),roots=[];for(let i=0;i<ts.length;i++){if(Math.abs(f(ts[i]))<1e-9)roots.push(ts[i]);if(!i||f(ts[i-1])*f(ts[i])>=0)continue;let lo=ts[i-1],hi=ts[i];for(let j=0;j<50;j++){const mid=(lo+hi)/2;if(f(lo)*f(mid)<=0)hi=mid;else lo=mid;}roots.push((lo+hi)/2);}return [...new Set(roots.map(t=>Math.round(t*1e12)/1e12))].filter(t=>{const x=cubic(a,b,t),u=((x.x-p.x)*dx+(x.y-p.y)*dy)/len;return u>=-1e-9&&u<=1+1e-9;});}
export function curveExtrema(a,b){const c=a.out||a,d=b.in||b,ts=[0,1];for(const axis of ['x','y']){const A=-a[axis]+3*c[axis]-3*d[axis]+b[axis],B=2*(a[axis]-2*c[axis]+d[axis]),C=c[axis]-a[axis];if(Math.abs(A)<1e-14){if(Math.abs(B)>1e-14)ts.push(-C/B);}else{const disc=B*B-4*A*C;if(disc>=0)ts.push((-B+Math.sqrt(disc))/(2*A),(-B-Math.sqrt(disc))/(2*A));}}return ts.filter(t=>t>=0&&t<=1).map(t=>cubic(a,b,t));}
export function pathExtrema(path){return [path,...path.subpaths||[]].flatMap(sp=>{const ps=[...sp.nodes||[]];for(let i=0;i<sp.nodes.length-(sp.closed?0:1);i++)ps.push(...curveExtrema(sp.nodes[i],sp.nodes[(i+1)%sp.nodes.length]));return ps;});}
